-- structure ------------------------------------------------------------------------------
select is((select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity and not exists (select 1 from pg_policies p where p.schemaname='public' and p.tablename=c.relname)), 3, 'exactly 3 RLS tables have no policy (deny-all)');
select is((select string_agg(c.relname, ',' order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not exists (select 1 from pg_policies p where p.schemaname='public' and p.tablename=c.relname)), 'device_credentials,device_tokens,pairing_tokens', 'deny-all tables are device_tokens, device_credentials, pairing_tokens');
select is((select count(*)::int from pg_policies where schemaname='public' and roles <> array['authenticated']::name[]), 0, 'every policy is restricted to authenticated');
select is((select count(*)::int from information_schema.column_privileges where table_schema='public' and grantee='anon'), 0, 'anon has no column privileges');
select ok(not has_any_column_privilege('authenticated','public.device_tokens','select,insert,update,references'), 'authenticated has no privilege on device_tokens');
select ok(not has_any_column_privilege('authenticated','public.device_credentials','select,insert,update,references'), 'authenticated has no privilege on device_credentials');
select ok(not has_any_column_privilege('authenticated','public.pairing_tokens','select,insert,update,references'), 'authenticated has no privilege on pairing_tokens');
select is((select count(*)::int from information_schema.routine_privileges where routine_schema='public' and grantee='authenticated' and routine_name in ('owns_family','owns_child','owns_device')), 3, 'authenticated can execute owns_* helpers');
reset role;
select set_config('request.jwt.claim.sub', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa', true);
set local role authenticated;
-- parent A: read isolation ---------------------------------------------------------------
select results_eq($$select count(*)::int, (count(*) filter (where id = 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'))::int from public.profiles$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in profiles, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where id = 'f0000000-0000-4000-8000-00000000000b'))::int from public.families$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in families, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where id = 'c0000000-0000-4000-8000-00000000000b'))::int from public.children$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in children, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.devices$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in devices, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.device_rules$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in device_rules, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.device_permissions$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in device_permissions, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.app_rules$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in app_rules, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.app_usage_daily$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in app_usage_daily, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.device_usage_daily$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in device_usage_daily, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.schedules$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in schedules, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.location_points$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in location_points, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.geofences$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in geofences, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.geofence_events$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in geofence_events, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.device_events$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in device_events, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where device_id = 'd0000000-0000-4000-8000-00000000000b'))::int from public.device_commands$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in device_commands, none of B''s');
select results_eq($$select count(*)::int, (count(*) filter (where parent_id = 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'))::int from public.audit_logs$$, $$values (1, 0)$$, 'A sees exactly its own row(s) in audit_logs, none of B''s');
select throws_ok($$select * from public.device_tokens$$, '42501', null, 'A cannot select device_tokens');
select throws_ok($$select * from public.device_credentials$$, '42501', null, 'A cannot select device_credentials');
select throws_ok($$select * from public.pairing_tokens$$, '42501', null, 'A cannot select pairing_tokens');
select throws_ok($$select fcm_token from public.device_tokens where device_id = 'd0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'A cannot read even its own device FCM token');
select throws_ok($$insert into public.pairing_tokens (child_id,created_by,token_hash,expires_at) values ('c0000000-0000-4000-8000-00000000000a','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',decode(repeat('ee',32),'hex'),now()+interval '5 minutes')$$, '42501', null, 'A cannot forge a pairing token');
select throws_ok($$update public.device_tokens set fcm_token = repeat('z',40)$$, '42501', null, 'A cannot update device_tokens');
select throws_ok($$delete from public.device_credentials$$, '42501', null, 'A cannot delete device_credentials (revocation is server-side)');
select results_eq($$select public.owns_family('f0000000-0000-4000-8000-00000000000a'), public.owns_family('f0000000-0000-4000-8000-00000000000b'), public.owns_child('c0000000-0000-4000-8000-00000000000a'), public.owns_child('c0000000-0000-4000-8000-00000000000b'), public.owns_device('d0000000-0000-4000-8000-00000000000a'), public.owns_device('d0000000-0000-4000-8000-00000000000b'), public.owns_device(null)$$, $$values (true,false,true,false,true,false,false)$$, 'owns_* helpers: own true, other/null false');
-- parent A: cross-family writes (IDOR by guessed UUID) ------------------------------------
select throws_ok($$insert into public.families (parent_id,name) values ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','x')$$, '42501', null, 'A cannot insert into families for B''s scope');
select throws_ok($$insert into public.children (family_id,name) values ('f0000000-0000-4000-8000-00000000000b','x')$$, '42501', null, 'A cannot insert into children for B''s scope');
select throws_ok($$insert into public.app_rules (device_id,package_name,app_name) values ('d0000000-0000-4000-8000-00000000000b','com.evil.app','x')$$, '42501', null, 'A cannot insert into app_rules for B''s scope');
select throws_ok($$insert into public.schedules (device_id,name,type,start_time,end_time,days) values ('d0000000-0000-4000-8000-00000000000b','x','CUSTOM','08:00','09:00','{1}')$$, '42501', null, 'A cannot insert into schedules for B''s scope');
select throws_ok($$insert into public.geofences (device_id,name,latitude,longitude,radius_meters) values ('d0000000-0000-4000-8000-00000000000b','x',1,1,100)$$, '42501', null, 'A cannot insert into geofences for B''s scope');
select throws_ok($$insert into public.device_commands (device_id,command_type,expires_at) values ('d0000000-0000-4000-8000-00000000000b','LOCK_NOW',now()+interval '5 minutes')$$, '42501', null, 'A cannot insert into device_commands for B''s scope');
update public.families set name='pwned' where id='f0000000-0000-4000-8000-00000000000b';
update public.children set name='pwned' where id='c0000000-0000-4000-8000-00000000000b';
update public.devices set device_name='pwned' where id='d0000000-0000-4000-8000-00000000000b';
update public.device_rules set location_enabled=true where device_id='d0000000-0000-4000-8000-00000000000b';
update public.app_rules set blocked=true where device_id='d0000000-0000-4000-8000-00000000000b';
update public.schedules set name='pwned' where device_id='d0000000-0000-4000-8000-00000000000b';
update public.geofences set name='pwned' where device_id='d0000000-0000-4000-8000-00000000000b';
update public.profiles set full_name='pwned' where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
delete from public.families where id='f0000000-0000-4000-8000-00000000000b';
delete from public.children where id='c0000000-0000-4000-8000-00000000000b';
delete from public.app_rules where device_id='d0000000-0000-4000-8000-00000000000b';
delete from public.schedules where device_id='d0000000-0000-4000-8000-00000000000b';
delete from public.geofences where device_id='d0000000-0000-4000-8000-00000000000b';
delete from public.location_points where device_id='d0000000-0000-4000-8000-00000000000b';
delete from public.app_usage_daily where device_id='d0000000-0000-4000-8000-00000000000b';
delete from public.device_usage_daily where device_id='d0000000-0000-4000-8000-00000000000b';
delete from public.geofence_events where device_id='d0000000-0000-4000-8000-00000000000b';
delete from public.device_events where device_id='d0000000-0000-4000-8000-00000000000b';
-- parent A: column / privilege restrictions on its OWN rows -----------------------------------
select throws_ok($$update public.families set parent_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb' where id='f0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'A cannot hand its family to B (parent_id immutable)');
select throws_ok($$update public.children set family_id='f0000000-0000-4000-8000-00000000000b' where id='c0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'A cannot move a child into Bs family');
select throws_ok($$update public.devices set child_id='c0000000-0000-4000-8000-00000000000b' where id='d0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'A cannot move a device to Bs child');
select throws_ok($$update public.devices set battery_level=1 where id='d0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'device-reported columns are not parent-writable');
select throws_ok($$update public.devices set enrollment_status='ENROLLED' where id='d0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'enrollment_status is not parent-writable');
select throws_ok($$update public.app_rules set device_id='d0000000-0000-4000-8000-00000000000b' where device_id='d0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'A cannot re-point an app rule to Bs device');
select throws_ok($$update public.profiles set email='x@example.test' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$, '42501', null, 'profiles.email is not writable');
select throws_ok($$update public.device_permissions set camera_status='GRANTED' where device_id='d0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'parent cannot write device_permissions');
select throws_ok($$delete from public.device_rules where device_id='d0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'parent cannot delete device_rules');
select throws_ok($$delete from public.devices where id='d0000000-0000-4000-8000-00000000000a'$$, '42501', null, 'parent cannot delete devices directly (revoke via Edge Function)');
select throws_ok($$insert into public.audit_logs (parent_id,action) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','LOGIN')$$, '42501', null, 'parent cannot write audit_logs');
select throws_ok($$update public.audit_logs set action='X_Y'$$, '42501', null, 'parent cannot update audit_logs');
select throws_ok($$delete from public.audit_logs$$, '42501', null, 'parent cannot delete audit_logs');
select throws_ok($$insert into public.device_usage_daily (device_id,usage_date,total_screen_minutes) values ('d0000000-0000-4000-8000-00000000000a',current_date - 1,1)$$, '42501', null, 'parent cannot forge usage data');
select throws_ok($$insert into public.location_points (device_id,latitude,longitude,accuracy_meters,recorded_at) values ('d0000000-0000-4000-8000-00000000000a',1,1,1,now())$$, '42501', null, 'parent cannot forge location points');
select throws_ok($$insert into public.device_events (device_id,event_type) values ('d0000000-0000-4000-8000-00000000000a','BATTERY_LOW')$$, '42501', null, 'parent cannot forge device events');
-- parent A: device_commands (PENDING-only, bounded expiry, no state changes) ---------------
select throws_ok($$insert into public.device_commands (device_id,command_type,expires_at,status) values ('d0000000-0000-4000-8000-00000000000a','LOCK_NOW',now()+interval '5 minutes','EXECUTED')$$, '42501', null, 'command insert cannot set status');
select throws_ok($$insert into public.device_commands (device_id,command_type,expires_at,executed_at) values ('d0000000-0000-4000-8000-00000000000a','LOCK_NOW',now()+interval '5 minutes',now())$$, '42501', null, 'command insert cannot set executed_at');
select throws_ok($$insert into public.device_commands (device_id,command_type,expires_at) values ('d0000000-0000-4000-8000-00000000000a','LOCK_NOW',now()+interval '3 days')$$, '42501', null, 'command expiry capped at 24 h');
select throws_ok($$insert into public.device_commands (device_id,command_type,expires_at) values ('d0000000-0000-4000-8000-00000000000a','LOCK_NOW',now()-interval '1 minute')$$, '42501', null, 'command cannot be created already expired');
select throws_ok($$update public.device_commands set status='EXECUTED'$$, '42501', null, 'parent cannot change command status (replay/forgery)');
select throws_ok($$delete from public.device_commands$$, '42501', null, 'parent cannot delete commands');
select lives_ok($$insert into public.device_commands (device_id,command_type,payload,expires_at) values ('d0000000-0000-4000-8000-00000000000a','SYNC_RULES','{"v":1}',now()+interval '10 minutes')$$, 'A can queue a PENDING command for own device');
select is((select status from public.device_commands where device_id='d0000000-0000-4000-8000-00000000000a' order by created_at desc, id limit 1), 'PENDING', 'queued command is PENDING');
-- parent A: legitimate writes ---------------------------------------------------------------
select lives_ok($$insert into public.families (parent_id,name) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Second family')$$, 'A can create a family');
select lives_ok($$insert into public.children (family_id,name,date_of_birth) values ('f0000000-0000-4000-8000-00000000000a','Kid A2','2015-01-01')$$, 'A can add a child');
select lives_ok($$update public.children set name='Renamed' where id='c0000000-0000-4000-8000-00000000000a'$$, 'A can rename own child');
