select lives_ok($$update public.app_rules set blocked=false, daily_limit_minutes=30 where device_id='d0000000-0000-4000-8000-00000000000a' and package_name='com.google.android.youtube'$$, 'A can update an app rule');
select lives_ok($$insert into public.schedules (device_id,name,type,start_time,end_time,days) values ('d0000000-0000-4000-8000-00000000000a','School','SCHOOL','08:00','15:00','{1,2,3,4,5}')$$, 'A can add a schedule (CHECK helper executable as authenticated)');
select lives_ok($$insert into public.geofences (device_id,name,latitude,longitude,radius_meters) values ('d0000000-0000-4000-8000-00000000000a','School',10,10,200)$$, 'A can add a geofence');
select lives_ok($$update public.geofences set radius_meters=300 where device_id='d0000000-0000-4000-8000-00000000000a' and name='School'$$, 'A can update a geofence');
select lives_ok($$update public.profiles set full_name='Parent A' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$, 'A can edit own profile name');
select lives_ok($$delete from public.location_points where device_id='d0000000-0000-4000-8000-00000000000a'$$, 'A can delete own location history');
select lives_ok($$delete from public.app_usage_daily where device_id='d0000000-0000-4000-8000-00000000000a'$$, 'A can delete own usage history');
select is((select count(*)::int from public.location_points), 0, 'A sees own location history gone');
-- B's data is untouched by all of A's attempts ----------------------------------------------
reset role;
select is((select count(*)::int from public.families where id='f0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in families survived A''s attacks');
select is((select count(*)::int from public.children where id='c0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in children survived A''s attacks');
select is((select count(*)::int from public.devices where id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in devices survived A''s attacks');
select is((select count(*)::int from public.device_rules where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in device_rules survived A''s attacks');
select is((select count(*)::int from public.app_rules where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in app_rules survived A''s attacks');
select is((select count(*)::int from public.schedules where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in schedules survived A''s attacks');
select is((select count(*)::int from public.geofences where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in geofences survived A''s attacks');
select is((select count(*)::int from public.location_points where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in location_points survived A''s attacks');
select is((select count(*)::int from public.app_usage_daily where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in app_usage_daily survived A''s attacks');
select is((select count(*)::int from public.device_usage_daily where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in device_usage_daily survived A''s attacks');
select is((select count(*)::int from public.geofence_events where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in geofence_events survived A''s attacks');
select is((select count(*)::int from public.device_events where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in device_events survived A''s attacks');
select is((select count(*)::int from public.device_commands where device_id='d0000000-0000-4000-8000-00000000000b'), 1, 'B''s row in device_commands survived A''s attacks');
select is((select count(*)::int from public.audit_logs where parent_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'), 1, 'B''s row in audit_logs survived A''s attacks');
select is((select name from public.families where id='f0000000-0000-4000-8000-00000000000b')||'|'||(select name from public.children where id='c0000000-0000-4000-8000-00000000000b')||'|'||(select device_name from public.devices where id='d0000000-0000-4000-8000-00000000000b')||'|'||coalesce((select full_name from public.profiles where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'-'), 'Fam B|Kid B|Phone B|-', 'B''s names are unchanged');
select is((select location_enabled from public.device_rules where device_id='d0000000-0000-4000-8000-00000000000b'), false, 'B''s device_rules unchanged');
select is((select blocked from public.app_rules where device_id='d0000000-0000-4000-8000-00000000000b'), false, 'B''s app rule unchanged');
reset role;
select set_config('request.jwt.claim.sub', 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb', true);
set local role authenticated;
select results_eq($$select (select count(*)::int from public.families), (select count(*)::int from public.devices), (select count(*)::int from public.location_points), (select count(*)::int from public.audit_logs)$$, $$values (1,1,1,1)$$, 'B sees only its own family/device/location/audit rows');
select is((select count(*)::int from public.families where id='f0000000-0000-4000-8000-00000000000a') + (select count(*)::int from public.devices where id='d0000000-0000-4000-8000-00000000000a'), 0, 'B cannot see A''s family or device');
-- anon, unauthenticated authenticated, device-style principals ---------------------------------
reset role;
set local role anon;
select throws_ok($$select * from public.families$$, '42501', null, 'anon cannot select families');
select throws_ok($$select * from public.children$$, '42501', null, 'anon cannot select children');
select throws_ok($$select * from public.devices$$, '42501', null, 'anon cannot select devices');
select throws_ok($$select * from public.location_points$$, '42501', null, 'anon cannot select location_points');
select throws_ok($$select * from public.audit_logs$$, '42501', null, 'anon cannot select audit_logs');
select throws_ok($$select * from public.device_tokens$$, '42501', null, 'anon cannot select device_tokens');
select throws_ok($$insert into public.families (parent_id,name) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','x')$$, '42501', null, 'anon cannot insert families');
select throws_ok($$select public.owns_device('d0000000-0000-4000-8000-00000000000a')$$, '42501', null, 'anon cannot call owns_device');
reset role;
select set_config('request.jwt.claim.sub', '', true);
set local role authenticated;
select is((select count(*)::int from public.families) + (select count(*)::int from public.devices) + (select count(*)::int from public.location_points) + (select count(*)::int from public.profiles), 0, 'authenticated role without a sub claim sees nothing');
select throws_ok($$insert into public.families (parent_id,name) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','x')$$, '42501', null, 'no sub claim: cannot insert a family');
reset role;
select set_config('request.jwt.claim.sub', 'd0000000-0000-4000-8000-00000000000a', true);
set local role authenticated;
select is((select count(*)::int from public.families) + (select count(*)::int from public.children) + (select count(*)::int from public.devices) + (select count(*)::int from public.device_commands) + (select count(*)::int from public.location_points) + (select count(*)::int from public.audit_logs) + (select count(*)::int from public.profiles), 0, 'a principal whose sub is a device id sees nothing via parent RLS');
select throws_ok($$insert into public.device_events (device_id,event_type) values ('d0000000-0000-4000-8000-00000000000a','DEVICE_ONLINE')$$, '42501', null, 'device-style principal cannot write device_events through parent grants');
reset role;
select * from finish();
rollback;
